function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function translateLocation(value, locale) {
  if (!value) return '';
  const exact = locale === 'zh' ? ZH_EXACT[value] : locale === 'ja' ? JA_EXACT[value] : null;
  const replacements = locale === 'zh' ? [...ZH_LOCATION_TERMS, ...ZH_EXTRA_TERMS, ...ZH_FINAL_TERMS, ...ZH_LAST_TERMS, ...ZH_ULTRA_TERMS, ...ZH_TERMS] : [...JA_LOCATION_TERMS, ...JA_EXTRA_TERMS, ...JA_TERMS, ...JA_FINAL_TERMS];
  let result = exact || value;
  for (const [from, to] of [...replacements].sort((a, b) => b[0].length - a[0].length)) {
    if (locale === 'zh' && from === 'post-') continue;
    const pattern = /^[A-Za-z0-9]+$/.test(from) ? `\\b${escapeRegExp(from)}\\b` : escapeRegExp(from);
    result = result.replace(new RegExp(pattern, 'gi'), to);
  }
  if (locale === 'zh') {
    result = result.replace(/\bPhase (\d+)\b/gi, '第$1阶段').replace(/\b(\d+)(?:st|nd|rd|th)-boss\b/gi, '第$1个Boss');
    result = result.replace(/\bpre (\d+)(?:st|nd|rd|th)-boss\b/gi, '第$1个Boss前').replace(/\bpost (\d+)(?:st|nd|rd|th)-boss\b/gi, '第$1个Boss后');
    result = result.replace(/\bbetween bosses\b/gi, 'Boss战之间').replace(/\bopening cutscene\b/gi, '开场过场动画');
    result = result.replace(/\bfinal boss\b/gi, '最终Boss').replace(/\bpost-battle\b/gi, '战斗后');
    result = result.replace(/\bsolo exploration\b/gi, '单人探索').replace(/\bSolo Instance\b/gi, '单人副本');
    result = result.replace(/\bMSQ\b/gi, '主线任务').replace(/\bday\b/gi, '白天').replace(/\bnight\b/gi, '夜晚');
    result = result.replace(/\bcutscenes?\b/gi, '过场动画').replace(/\bcombat\b/gi, '战斗').replace(/\bbattles?\b/gi, '战斗');
    result = result.replace(/\btheme\b/gi, '主题').replace(/\bcredits\b/gi, '片尾');
    result = result.replace(/\bFFXIII\b/gi, '最终幻想13').replace(/\bFFXIV\b/gi, '最终幻想14').replace(/\bFFXV\b/gi, '最终幻想15');
    result = result.replace(/最终幻想XIII/g, '最终幻想13').replace(/最终幻想XIV/g, '最终幻想14').replace(/最终幻想XVI/g, '最终幻想16').replace(/最终幻想XV/g, '最终幻想15');
    result = result.replace(/\bFist of Father\b/gi, '启动之章').replace(/\bSDS\b/gi, '芬里尔').replace(/\bVII\b/gi, '七');
    result = result.replace(/\bPod\b/gi, '自走人偶').replace(/\bDragon-king\b/gi, '龙王').replace(/\bAlpha Omega\b/gi, '阿尔法欧米茄');
    result = result.replace(/\bLynx of Righteous Fire\b/gi, '正义之火灵狮').replace(/\bLoading\b/gi, '加载').replace(/\bType-G\b/gi, 'G型');
    result = result.replace(/\bConstruct VII\b/gi, '构造体七号').replace(/\b9S-operated\b/gi, '9S操纵').replace(/\bDiablo Armament\b/gi, '迪亚波罗斯兵装');
    result = result.replace(/\bArgath Thadulfus\b/gi, '阿格斯·萨德法斯').replace(/\bAmalj'aa\b/gi, '蜥蜴人族');
    result = result.replace(/Dragon-/gi, '龙王').replace(/纳尔扎尔'thal/gi, '纳尔扎尔');
  } else {
    result = result.replace(/\bPhase (\d+)\b/gi, 'フェーズ$1').replace(/\b(\d+)(?:st|nd|rd|th)-boss\b/gi, '$1体目のボス');
    result = result.replace(/\bpre (\d+)(?:st|nd|rd|th)-boss\b/gi, '$1体目のボス前').replace(/\bpost (\d+)(?:st|nd|rd|th)-boss\b/gi, '$1体目のボス後');
    result = result.replace(/\bbetween bosses\b/gi, 'ボス間').replace(/\bopening cutscene\b/gi, 'オープニングカットシーン');
    result = result.replace(/\bfinal boss\b/gi, '最終ボス').replace(/\bpost-battle\b/gi, '戦闘後');
    result = result.replace(/\bsolo exploration\b/gi, 'ソロ探索').replace(/\bSolo Instance\b/gi, 'ソロインスタンス');
    result = result.replace(/\bMSQ\b/gi, 'メインクエスト').replace(/\bday\b/gi, '昼').replace(/\bnight\b/gi, '夜');
    result = result.replace(/\bcutscenes?\b/gi, 'カットシーン').replace(/\bcombat\b/gi, '戦闘').replace(/\bbattles?\b/gi, '戦闘');
    result = result.replace(/\btheme\b/gi, 'テーマ').replace(/\bcredits\b/gi, 'エンディング');
  }
  return result.replace(/\s{2,}/g, ' ').replace(/\(\s+/g, '(').replace(/\s+\)/g, ')').trim();
}

export const BGM_LOCATIONS_EN = BGM_LOCATIONS;
export const BGM_LOCATIONS_ZH = Object.freeze(Object.fromEntries(Object.entries(BGM_LOCATIONS).map(([id, value]) => [id, translateLocation(value, 'zh')])));
export const BGM_LOCATIONS_JA = Object.freeze(Object.fromEntries(Object.entries(BGM_LOCATIONS).map(([id, value]) => [id, translateLocation(value, 'ja')])));

function overrideNames(override, locale) {
  if (Array.isArray(override?.names)) return override.names;
  return Array.isArray(override?.names?.[locale]) ? override.names[locale] : [];
}

export function bgmLocation(id, locale = 'zh') {
  const maps = { zh: BGM_LOCATIONS_ZH, en: BGM_LOCATIONS_EN, ja: BGM_LOCATIONS_JA };
  return maps[locale]?.[id] || maps.zh[id] || overrideNames(BGM_USAGE_OVERRIDES[id], locale)[0] || '';
}

export function bgmLocations(ids, locale = 'zh') {
  const values = [];
  for (const id of Array.isArray(ids) ? ids : []) {
    const value = bgmLocation(id, locale);
    if (value && !values.includes(value)) values.push(value);
  }
  return values;
}
